mentor.sparql.listGraphsQuery.default:
SELECT DISTINCT ?graph
WHERE 
{
    GRAPH ?graph { ?s ?p ?o }
}
ORDER BY ?graph

mentor.sparql.describeQueryTemplate.default:
---
params {
  resourceIri: iri
  graphIris:   iri[] optional
}
---
CONSTRUCT { ${resourceIri} ?p ?o }
{% for g in graphIris %}
FROM ${g}
{% endfor %}
WHERE { ${resourceIri} ?p ?o }

mentor.sparql.exportGraphQuery.default:
---
params {
  graphIri: iri
}
---
CONSTRUCT {
    ?s ?p ?o .
} WHERE {
    GRAPH ${graphIri} {
        ?s ?p ?o .
    }
}

mentor.sparql.countGraphQuery.default:
---
params {
  graphIri: iri
  limit:    int optional
}
---
SELECT (COUNT(?s) as ?count)
WHERE {
    SELECT ?s
    WHERE {
        GRAPH ${graphIri} {
            ?s ?p ?o .
        }
    }
    {% if limit %}LIMIT ${limit}{% endif %}
}

mentor.language.sparql.documentQueryTemp.default:
---
params {
  documentIri: iri
}
example rdf {
  documentIri: "http://www.w3.org/1999/02/22-rdf-syntax-ns#"
}
---
SELECT * WHERE { ${documentIri} ?p ?o }
